    },
    {
      "resourceType": "Observation",
      "id": "observation-31",
      "status": "final",
      "code": {
        "text": "Neurological examination"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Baseline mild left arm weakness only"
    }
  ]
}

